//! Writes `src/generated/*.rs`.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use anyhow::Result;

use crate::expr::{Arena, E};
use crate::names;

/// Header of every generated file: the files are BSD-3 derived data.
pub fn header(release: &str) -> String {
    format!(
        "// @generated by aarch64-isa-gen from {release}. Do not edit.\n\
         //\n\
         // Derived from Arm's AARCHMRS (Arm Architecture Machine Readable Specification),\n\
         // Copyright (c) 2010-2026 Arm Limited or its affiliates, licensed under the\n\
         // BSD 3-clause license. See THIRD_PARTY_NOTICES at the repository root.\n\n"
    )
}

/// A plain `#[repr(u16)]` enum with a name table, `values()` and `from_index()`.
pub fn simple_enum(
    out: &mut String,
    doc: &str,
    name: &str,
    variants: &[(String, String, String)],
    first_doc: Option<&str>,
) {
    let n = variants.len();
    let _ = writeln!(out, "{doc}");
    let _ = writeln!(
        out,
        "#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash{})]\n\
         #[allow(non_camel_case_types)]\n#[repr(u16)]\npub enum {name} {{",
        if first_doc.is_some() { ", Default" } else { "" }
    );
    for (i, (v, _, d)) in variants.iter().enumerate() {
        if i == 0 {
            if let Some(fd) = first_doc {
                let _ = writeln!(out, "    /// {fd}");
                let _ = writeln!(out, "    #[default]");
            } else if !d.is_empty() {
                let _ = writeln!(out, "    /// {d}");
            }
        } else if !d.is_empty() {
            let _ = writeln!(out, "    /// {d}");
        }
        let _ = writeln!(out, "    {v} = {i},");
    }
    let _ = writeln!(out, "}}\n");
    let upper = name.to_ascii_uppercase();
    let _ = writeln!(out, "pub(crate) const {upper}_COUNT: usize = {n};\n");
    let _ = writeln!(out, "static {upper}_NAMES: [&str; {n}] = [");
    for (_, s, _) in variants {
        let _ = writeln!(out, "    {s:?},");
    }
    let _ = writeln!(out, "];\n");
    let _ = writeln!(out, "static {upper}_VALUES: [{name}; {n}] = [");
    for (v, _, _) in variants {
        let _ = writeln!(out, "    {name}::{v},");
    }
    let _ = writeln!(out, "];\n");
    let _ = writeln!(
        out,
        "impl {name} {{\n\
         \x20   /// Every value, in discriminant order.\n\
         \x20   pub fn values() -> impl ExactSizeIterator<Item = {name}> + DoubleEndedIterator + Clone {{\n\
         \x20       {upper}_VALUES.iter().copied()\n\
         \x20   }}\n\n\
         \x20   /// The value with discriminant `i`.\n\
         \x20   pub fn from_index(i: usize) -> Option<{name}> {{\n\
         \x20       {upper}_VALUES.get(i).copied()\n\
         \x20   }}\n\n\
         \x20   /// The spec's name.\n\
         \x20   pub fn name(self) -> &'static str {{\n\
         \x20       {upper}_NAMES[self as usize]\n\
         \x20   }}\n\n\
         \x20   /// The value with this spec name.\n\
         \x20   pub fn from_name(name: &str) -> Option<{name}> {{\n\
         \x20       {upper}_NAMES.iter().position(|n| *n == name).and_then(Self::from_index)\n\
         \x20   }}\n\
         }}\n"
    );
}

/// The `Register` enum: not spec data, but mechanical, so generated too.
pub fn registers() -> String {
    let mut v: Vec<(String, String, String)> = vec![("None".into(), "".into(), String::new())];
    let mut push = |var: String, name: String| v.push((var, name, String::new()));
    for i in 0..31 {
        push(format!("W{i}"), format!("w{i}"));
    }
    push("WZR".into(), "wzr".into());
    push("WSP".into(), "wsp".into());
    for i in 0..31 {
        push(format!("X{i}"), format!("x{i}"));
    }
    push("XZR".into(), "xzr".into());
    push("SP".into(), "sp".into());
    for p in ["B", "H", "S", "D", "Q", "V", "Z"] {
        for i in 0..32 {
            push(format!("{p}{i}"), format!("{}{i}", p.to_ascii_lowercase()));
        }
    }
    for i in 0..16 {
        push(format!("P{i}"), format!("p{i}"));
    }
    for i in 0..16 {
        push(format!("PN{i}"), format!("pn{i}"));
    }
    push("ZA".into(), "za".into());
    push("ZT0".into(), "zt0".into());
    for (p, n) in [("ZAB", 1), ("ZAH", 2), ("ZAS", 4), ("ZAD", 8), ("ZAQ", 16)] {
        for i in 0..n {
            push(
                format!("{p}{i}"),
                format!("za{i}.{}", p[2..].to_ascii_lowercase()),
            );
        }
    }
    for (var, name) in [
        ("NZCV", "nzcv"),
        ("FPCR", "fpcr"),
        ("FPSR", "fpsr"),
        ("FFR", "ffr"),
        ("PC", "pc"),
    ] {
        push(var.into(), name.into());
    }
    let mut out = String::new();
    simple_enum(
        &mut out,
        "/// A register. `XZR`/`SP` (and `WZR`/`WSP`) are distinct even though both are\n\
         /// encoding 31. `NZCV`, `FPCR`, `FPSR`, `FFR` and `PC` appear only as implicit\n\
         /// operands in instruction info.",
        "Register",
        &v,
        Some("No register."),
    );
    out
}

fn binop(op: &str) -> &'static str {
    match op {
        "==" => "Eq",
        "!=" => "Ne",
        "&&" => "And",
        "||" => "Or",
        "<" => "Lt",
        ">" => "Gt",
        ">=" => "Ge",
        "<=" => "Le",
        "+" => "Add",
        "-" => "Sub",
        "MOD" => "Mod",
        "XOR" => "Xor",
        "::" => "Concat",
        _ => unreachable!("operator {op} passed compilation"),
    }
}

/// `EXPRS` and `EXPR_ARGS`.
pub fn exprs(arena: &Arena, features: &BTreeMap<String, String>) -> String {
    let mut args: Vec<u32> = Vec::new();
    let mut body = String::new();
    for e in &arena.nodes {
        let s = match e {
            E::Bool(b) => format!("Bool({b})"),
            E::Field { lsb, width } => format!("Field {{ lsb: {lsb}, width: {width} }}"),
            E::Bits { value, mask, width } => {
                format!("Bits {{ value: {value:#x}, mask: {mask:#x}, width: {width} }}")
            }
            E::Int(i) => format!("Int({i})"),
            E::Feature(f) => format!("Feature(Feature::{})", features[f]),
            E::Not(a) => format!("Not({a})"),
            E::BitNot(a) => format!("BitNot({a})"),
            E::Bin(op, a, b) => format!("Bin(BinOp::{}, {a}, {b})", binop(op)),
            E::In(a, m) => {
                let start = args.len();
                args.extend(m);
                format!("In({a}, {start}, {})", m.len())
            }
            E::Slice(a, hi, lo) => format!("Slice({a}, {hi}, {lo})"),
            E::UInt(a) => format!("UInt({a})"),
            E::Call(f, a) => {
                let start = args.len();
                args.extend(a);
                format!("Call(Func::{f}, {start}, {})", a.len())
            }
        };
        let _ = writeln!(body, "    Expr::{s},");
    }
    // The table is the reference the compiled conditions (`conds.rs`) are tested
    // against.
    let mut out = String::new();
    let _ = writeln!(
        out,
        "#[cfg(test)]\npub(crate) static EXPRS: [Expr; {}] = [\n{body}];\n",
        arena.nodes.len()
    );
    let _ = writeln!(
        out,
        "#[cfg(test)]\npub(crate) static EXPR_ARGS: [u16; {}] = [",
        args.len()
    );
    for chunk in args.chunks(16) {
        let line: Vec<String> = chunk.iter().map(|a| a.to_string()).collect();
        let _ = writeln!(out, "    {},", line.join(", "));
    }
    let _ = writeln!(out, "];\n");
    out
}

/// `conds.rs`: every expression of the arena compiled to a function built from the
/// evaluator's helpers (`crate::cond`), so a compiled condition computes exactly what
/// interpreting `EXPRS` does, without walking the table. `CONDS[id]` is expression
/// `id` as a condition.
pub fn cond_fns(arena: &Arena, features: &BTreeMap<String, String>) -> String {
    let mut out = String::from(
        "#[allow(unused_imports)]\n\
         use crate::cond::{BinOp, Ctx, Func, Val, bin, bit_not, call, equal, field, not, slice, uint};\n\
         use crate::generated::Feature;\n\n",
    );
    for (i, e) in arena.nodes.iter().enumerate() {
        let body = match e {
            E::Bool(b) => format!("Val::Bool({b})"),
            E::Field { lsb, width } => format!("field(cx, {lsb}, {width})"),
            E::Bits { value, mask, width } => {
                format!("Val::Bits {{ value: {value:#x}, mask: {mask:#x}, width: {width} }}")
            }
            E::Int(v) => format!("Val::Int({v})"),
            E::Feature(f) => format!("Val::Bool(cx.features.has(Feature::{}))", features[f]),
            E::Not(a) => format!("not(e{a}(cx))"),
            E::BitNot(a) => format!("bit_not(e{a}(cx))"),
            // The logical operators short-circuit, as the evaluator does.
            E::Bin(op, a, b) if op == "&&" => {
                format!("Val::Bool(e{a}(cx).truthy() && e{b}(cx).truthy())")
            }
            E::Bin(op, a, b) if op == "||" => {
                format!("Val::Bool(e{a}(cx).truthy() || e{b}(cx).truthy())")
            }
            E::Bin(op, a, b) => format!("bin(BinOp::{}, e{a}(cx), e{b}(cx))", binop(op)),
            E::In(a, m) => {
                let tests: Vec<String> = m.iter().map(|m| format!("equal(x, e{m}(cx))")).collect();
                format!("{{ let x = e{a}(cx); Val::Bool({}) }}", tests.join(" || "))
            }
            E::Slice(a, hi, lo) => format!("slice(e{a}(cx), {hi}, {lo})"),
            E::UInt(a) => format!("uint(e{a}(cx))"),
            E::Call(f, a) => {
                let args: Vec<String> = a.iter().map(|a| format!("e{a}(cx)")).collect();
                format!("call(Func::{f}, &[{}])", args.join(", "))
            }
        };
        let _ = writeln!(
            out,
            "#[inline(always)]\n#[allow(unused_variables)]\nfn e{i}(cx: &Ctx<'_>) -> Val {{\n    {body}\n}}\n\
             fn c{i}(cx: &Ctx<'_>) -> bool {{\n    e{i}(cx).truthy()\n}}\n"
        );
    }
    let _ = writeln!(
        out,
        "pub(crate) static CONDS: [fn(&Ctx<'_>) -> bool; {}] = [",
        arena.nodes.len()
    );
    for i in 0..arena.nodes.len() {
        let _ = writeln!(out, "    c{i},");
    }
    let _ = writeln!(out, "];");
    // The `SysOpIs` calls name a system instruction alias by its index here.
    let _ = writeln!(
        out,
        "\n/// System instruction aliases, by the index `SysOpIs` conditions use.\n\
         pub(crate) static SYSOP_NAMES: [&str; {}] = [",
        crate::expr::SYSOP_NAMES.len()
    );
    for n in crate::expr::SYSOP_NAMES {
        let _ = writeln!(out, "    {n:?},");
    }
    let _ = writeln!(out, "];");
    out
}

/// Writes `s` to `path` only if it differs, so unchanged files keep their mtime.
/// `--check`: compare instead of writing, and collect the files that differ.
pub static CHECK: std::sync::Mutex<Option<Vec<String>>> = std::sync::Mutex::new(None);

/// Writes `s` to `path` only if it differs, so unchanged files keep their mtime. In
/// `--check` mode, records the path instead.
pub fn write(path: &std::path::Path, s: &str) -> Result<()> {
    if std::fs::read_to_string(path).ok().as_deref() != Some(s) {
        let mut check = CHECK.lock().expect("check lock");
        match check.as_mut() {
            Some(v) => v.push(path.display().to_string()),
            None => std::fs::write(path, s)?,
        }
    }
    Ok(())
}

pub fn feature_variants(names: &[String]) -> BTreeMap<String, String> {
    names
        .iter()
        .map(|n| (n.clone(), names::feature_variant(n)))
        .collect()
}

const KEYWORDS: &[&str] = &[
    "as", "break", "const", "continue", "crate", "else", "enum", "extern", "false", "fn", "for",
    "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return",
    "self", "static", "struct", "super", "trait", "true", "type", "unsafe", "use", "where",
    "while", "async", "await", "dyn", "abstract", "become", "box", "do", "final", "macro",
    "override", "priv", "typeof", "unsized", "virtual", "yield", "try", "gen",
];

fn ident(s: &str) -> String {
    if KEYWORDS.contains(&s) {
        format!("r#{s}")
    } else {
        s.to_string()
    }
}

/// `CodeAssembler` methods, one per mnemonic (and suffix) and operand count, and the
/// lower-case register constants.
/// The method without a count suffix has the smallest operand count of the
/// encodings outside SVE/SME (so their methods keep their names as SVE and SME
/// forms are added), or of all when there are none.
pub fn code_asm(asm: &BTreeMap<(String, String), BTreeMap<usize, bool>>) -> String {
    let mut out = String::new();
    out.push_str(
        "use crate::code_asm::CodeAssembler;\nuse crate::encoder::EncodeError;\nuse crate::generated::Mnemonic;\nuse crate::operand::Operand;\n\n\
         #[allow(clippy::too_many_arguments)]\nimpl CodeAssembler {\n",
    );
    let mut seen = std::collections::BTreeSet::new();
    for ((m, s), arities) in asm {
        let base = format!("{}{}", m.to_ascii_lowercase(), s.to_ascii_lowercase());
        let min = arities
            .iter()
            .find(|(_, base)| **base)
            .or_else(|| arities.iter().next())
            .map_or(0, |(n, _)| *n);
        // `_cond` names a condition-suffix form; it is passed as an operand.
        let s = if s == "_cond" { "" } else { s.as_str() };
        for &n in arities.keys() {
            let name = if n == min {
                base.clone()
            } else {
                format!("{base}_{n}")
            };
            if !seen.insert(name.clone()) {
                continue;
            }
            let params: Vec<String> = (0..n)
                .map(|i| format!("a{i}: impl Into<Operand>"))
                .collect();
            let args: Vec<String> = (0..n).map(|i| format!("a{i}.into()")).collect();
            let _ = writeln!(
                out,
                "    /// `{m}{s}` with {n} operands.\n    pub fn {}(&mut self{}{}) -> Result<&mut Self, EncodeError> {{\n        self.emit(Mnemonic::{}, {s:?}, &[{}])\n    }}\n",
                ident(&name),
                if n > 0 { ", " } else { "" },
                params.join(", "),
                names::mnemonic_variant(m),
                args.join(", ")
            );
        }
    }
    out.push_str("}\n\n/// Lower-case register names for assembler code (`a.add(x0, x1, x2)`).\n#[allow(non_upper_case_globals)]\npub mod registers {\n    use crate::generated::Register;\n");
    let regs = registers();
    for line in regs.lines() {
        // `    W0 = 1,` lines of the enum.
        let t = line.trim();
        if let Some((v, _)) = t.split_once(" = ") {
            if v == "None" || !v.chars().all(|c| c.is_ascii_alphanumeric()) {
                continue;
            }
            let lower = v.to_ascii_lowercase();
            if v.starts_with("ZA") && v.len() > 2
                || matches!(v, "NZCV" | "FPCR" | "FPSR" | "FFR" | "PC")
            {
                continue;
            }
            let _ = writeln!(out, "    pub const {lower}: Register = Register::{v};");
        }
    }
    out.push_str("}\n");
    out
}

/// `src/generated/mod.rs`.
pub const MOD_RS: &str = r#"#[rustfmt::skip]
#[allow(clippy::all, clippy::pedantic)]
mod code;
#[rustfmt::skip]
#[allow(clippy::all, clippy::pedantic)]
pub(crate) mod conds;
#[cfg(feature = "code_asm")]
#[rustfmt::skip]
#[allow(clippy::all, clippy::pedantic)]
pub(crate) mod code_asm;
#[rustfmt::skip]
#[allow(clippy::all, clippy::pedantic)]
mod register;
#[rustfmt::skip]
#[allow(clippy::all, clippy::pedantic)]
pub(crate) mod sysreg;
#[rustfmt::skip]
#[allow(clippy::all, clippy::pedantic)]
pub(crate) mod tables;

pub(crate) use code::{CODE_COUNT, FEATURE_COUNT, MNEMONIC_COUNT};
pub use code::{Code, Feature, Mnemonic};
pub(crate) use register::REGISTER_COUNT;
pub use register::Register;
"#;
